<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\Holder\ConsentPurposeRequiredAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ConsentPurposeRequiredAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class ConsentPurposeRequiredAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isRequired returns null on a freshly created holder.
     */
    public function testRequiredNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithConsentPurposeRequiredAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isRequiredAssigned());
        $this->assertNull($holder->isRequired());
    }
}
class ImplWithConsentPurposeRequiredAttributeHolderUnitTest
{
    use ConsentPurposeRequiredAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRequiredRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRequired();
    }
}
